"use client";

import { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Play, Image as ImageIcon, Search } from "lucide-react";

export default function MediaStage({ images, videoId }: { images: string[], videoId: string }) {
  const [index, setIndex] = useState(0);
  const [activeMode, setActiveMode] = useState<"image" | "video">("image");
  const [isZoomed, setIsZoomed] = useState(false);
  
  const lastTap = useRef<number>(0);

  // --- ZOOM CONFIGURATION ---
  const ZOOM_LEVEL = 2.5;

  /**
   * Handle Interaction
   * Strictly detects double-tap to toggle zoom state.
   * Single clicks are ignored to prevent accidental zoom resets during panning.
   */
  const handleInteraction = (e: React.PointerEvent) => {
    const now = Date.now();
    const DOUBLE_TAP_THRESHOLD = 300;

    if (now - lastTap.current < DOUBLE_TAP_THRESHOLD) {
      // Toggle zoom only on double-tap
      setIsZoomed(!isZoomed); 
      // Reset lastTap to prevent a triple-tap from triggering another toggle immediately
      lastTap.current = 0; 
      return;
    }
    
    lastTap.current = now;
  };

  const handleDragEnd = (event: any, info: any) => {
    // Disable carousel navigation while zoomed to allow for image panning
    if (isZoomed) return;

    const threshold = 50;
    if (info.offset.x < -threshold) {
      if (index < images.length - 1) setIndex(index + 1);
      else setActiveMode("video");
    } else if (info.offset.x > threshold) {
      if (activeMode === "video") setActiveMode("image");
      else if (index > 0) setIndex(index - 1);
    }
  };

  return (
    <div className="relative w-full group select-none touch-none">
      
      {/* --- MEDIA VIEWPORT (Editorial Window) --- */}
      <div 
        className="relative aspect-4/5 rounded-4xl overflow-hidden border border-border cursor-crosshair"
        onPointerDown={handleInteraction}
      >
        <AnimatePresence mode="wait">
          {activeMode === "image" ? (
            <motion.div
              key={`img-wrap-${index}`}
              className="w-full h-full overflow-hidden bg-white"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
            >
              <motion.div
                key={`img-content-${index}`}
                // Drag Behavior: 
                // Full axis panning when zoomed, horizontal-only for swipe when normal.
                drag={isZoomed ? true : "x"}
                
                // Constraints: Kept generous so user can "inspect all sides" as requested.
                dragConstraints={isZoomed ? {
                  left: -500, 
                  right: 500,
                  top: -600,
                  bottom: 600
                } : { left: 0, right: 0 }}
                
                dragElastic={isZoomed ? 0.05 : 0.5}
                onDragEnd={handleDragEnd}
                className="w-full h-full"
              >
                <motion.img
                  src={images[index]}
                  alt="Product Detail"
                  className="w-full h-full object-cover pointer-events-none"
                  // Zoom scaling only affects the image pixels, not the UI container
                  animate={{ 
                    scale: isZoomed ? ZOOM_LEVEL : 1,
                  }}
                  transition={{ 
                    type: "spring", 
                    stiffness: 150, 
                    damping: 25 
                  }}
                />
              </motion.div>
            </motion.div>
          ) : (
            <motion.div
              key="video-stage"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="w-full h-full bg-black"
            >
              <iframe
                src={`https://www.youtube.com/embed/${videoId}?autoplay=1&mute=1&loop=1&playlist=${videoId}&controls=0&modestbranding=1&rel=0`}
                className="w-full h-full object-cover scale-150 pointer-events-none"
                allow="autoplay"
              />
            </motion.div>
          )}
        </AnimatePresence>


        {/* Visual Zoom Feedback */}
        <div className="absolute top-10 right-10">
           <div className={`p-2 rounded-full border transition-all duration-500 ${isZoomed ? "bg-brand border-brand text-brand-foreground" : "bg-white/5 border-white/10 text-white"}`}>
              <Search size={14} />
           </div>
        </div>
      </div>

      {/* --- CAPSULE MODE SWITCHER --- */}
      <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-20">
        <div className="bg-background/30 backdrop-blur-3xl border border-white p-1 rounded-full flex items-center gap-1">
          <button
            onClick={() => { setActiveMode("image"); setIndex(0); setIsZoomed(false); }}
            className={`flex items-center gap-1 px-4 py-1 rounded-full text-[8px] font-black uppercase tracking-widest transition-all ${
              activeMode === "image" ? "bg-foreground text-background" : "text-foreground opacity-40 hover:opacity-100"
            }`}
          >
            <ImageIcon size={14} /> images
          </button>
          <button
            onClick={() => { setActiveMode("video"); setIsZoomed(false); }}
            className={`flex items-center gap-1 px-4 py-1 rounded-full text-[8px] font-black uppercase tracking-widest transition-all ${
              activeMode === "video" ? "bg-foreground text-background" : "text-foreground opacity-40 hover:opacity-100"
            }`}
          >
            <Play size={14} fill="currentColor" /> video
          </button>
        </div>
      </div>

      {/* Vertical Status Scrubber */}
      <div className="absolute top-1/2 -translate-y-1/2 right-6 flex flex-col gap-2">
        {images.map((_, i) => (
          <div key={i} className={`w-1 transition-all duration-500 rounded-full ${activeMode === 'image' && index === i ? "h-8 bg-white" : "h-2 bg-white/20"}`} />
        ))}
        <div className={`w-1 transition-all duration-500 rounded-full ${activeMode === 'video' ? "h-8 bg-brand" : "h-2 bg-white/20"}`} />
      </div>
    </div>
  );
}